/**
 * @name Unsafe deserialization flow
 * @description Traces flow from function parameters to pickle.loads
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-deserialization-flow
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PickleFlowConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    sink = API::moduleImport("pickle").getMember(["load", "loads"]).getACall().getArg(0)
  }
}

module PickleFlow = TaintTracking::Global<PickleFlowConfig>;
import PickleFlow::PathGraph

from PickleFlow::PathNode source, PickleFlow::PathNode sink
where PickleFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Pickle deserialization from $@.", source.getNode(), "parameter"

/**
 * @name Pickle data flow
 * @description Trace data flow to pickle.loads
 * @kind path-problem
 * @problem.severity error
 * @id py/pickle-data-flow
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PickleFlowConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember("loads").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleFlow = TaintTracking::Global<PickleFlowConfig>;
import PickleFlow::PathGraph

from PickleFlow::PathNode source, PickleFlow::PathNode sink
where PickleFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Pickle deserialization from $@.", source.getNode(), "parameter"
